from Crypto.Util.number import long_to_bytes, bytes_to_long, getPrime
import math

def continued_fraction(p, q):
    res = []
    b = 1
    while b != 0:
        res.append(p // q)
        b = p % q
        p = q
        q = b
    return res


def suitable_fraction(p, q):
    coefficient = continued_fraction(p, q)
    P, Q = [coefficient[0], coefficient[0] * coefficient[1] + 1], [1, coefficient[1]]
    for i in range (2, len(coefficient)):
        P.append(P[i - 1] * coefficient[i] + P[i - 2])
        Q.append(Q[i - 1] * coefficient[i] + Q[i - 2])
    return P, Q


def attack(e, n, number):
    counter = 1
    P, Q = suitable_fraction(e, n)
    p, q = 1, 1
    for i in range(len(continued_fraction(e, n))):
        p, q = P[i], Q[i]
        if p == 0:
            continue
        if (e * q) % p == 1:
            if counter == number:
                break
            else:
                counter += 1
    return q


def yakobi(a, n):
    g = 1
    s = 0
    while 1:
        if a == 0: return 0
        elif a == 1: return g
        k = 0
        while a % 2 != 1:
            a //= 2
            k += 1
        a1 = a
        if (k % 2 == 0) or (n % 8 == 1) or (n % 8 == 7): s = 1
        elif (n % 8 == 3) or (n % 8 == 5): s = -1
        if a1 == 1: return g * s
        if (n % 4 == 3) and (a1 % 4 == 3): s = -s
        a = n % a1
        n = a1
        g *= s
        # print(f'k = {k}\ns = {s}\na = {a}\nn = {n}\ng = {g}\n')


def find_khN(p):
    N = 1
    while yakobi(N, p) != -1:
        N += 1
    p -= 1
    k = 0
    while p % 2 != 1:
        p //= 2
        k += 1
    return k, p, N


def solve_p2(a, p):
    if yakobi(a, p) != 1:
        print("not root")
        return 0
    k, h, N = find_khN(p)
    a1 = pow(a, (h+1)//2, p)
    a2 = pow(a, -1, p)
    N1 = pow(N, h, p)
    N2 = 1
    j = 0
    for i in range(k-1):
        b = a1 * N2 % p
        c = a2 * pow(b, 2, p) % p
        d = pow(c, pow(2, k - 2 - i), p)
        if d == 1: j = 0
        elif d == p - 1: j = 1
        N2 = N2 * pow(N1, 2**i * j) % p
    return a1 * N2 % p


def cto(m, a):
    if math.gcd(*m) != 1:
        print("Not simple")
        return 0
    M = math.prod(m)
    x = 0
    for i in range(len(m)):
        n = pow(M // m[i], -1, m[i])
        x += M // m[i] * a[i] * n % M
    return x


